const {classify}=require('./classify.cjs');exports.resume=(q,id)=>q.map(x=>x.id===id&&x.state==='uncertain'?{...x,state:'ready'}:x);exports.drain=async(q,post,persist)=>{const out=[];let stop=false;for(const item of q){if(stop||item.state!=='ready'){out.push(item);continue}try{await post(item)}catch(e){const s=classify(e);out.push({...item,state:s});if(s==='uncertain')stop=true}}await persist(out);return out;};
